CARDIO.register({"item":"p207","meta":{"num":"p207","label":"207","spe":"pneumo","short":"Opacités et masses","title":"Opacités et masses intra-thoraciques","section":"P","chapter":11,"pages":"151-170","sdd":[]},"objectives":[{"id":"p207-obj-01","rank":"A","rubric":"Diagnostic positif","title":"Connaître les modalités de prescription d'une radiographie thoracique en urgence","desc":""},{"id":"p207-obj-02","rank":"A","rubric":"Diagnostic positif","title":"Connaître les modalités du diagnostic d'une opacité pulmonaire","desc":""},{"id":"p207-obj-03","rank":"A","rubric":"Diagnostic positif","title":"Connaître les modalités du diagnostic d'un épanchement pleural liquidien","desc":""},{"id":"p207-obj-04","rank":"A","rubric":"Diagnostic positif","title":"Connaître les modalités du diagnostic d'un épanchement pleural gazeux","desc":""},{"id":"p207-obj-05","rank":"B","rubric":"Diagnostic positif","title":"Connaître les modalités du diagnostic d'un syndrome alvéolaire","desc":""},{"id":"p207-obj-06","rank":"B","rubric":"Diagnostic positif","title":"Connaître les modalités du diagnostic d'un syndrome interstitiel","desc":""},{"id":"p207-obj-07","rank":"B","rubric":"Diagnostic positif","title":"Connaître les modalités du diagnostic d'une anomalie médiastinale","desc":""},{"id":"p207-obj-08","rank":"B","rubric":"Diagnostic positif","title":"Connaître les modalités du diagnostic d'une atélectasie","desc":""},{"id":"p207-obj-09","rank":"B","rubric":"Étiologies","title":"Connaître les principales hypothèses diagnostiques devant une anomalie médiastinale selon la topographie","desc":""}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"p207-qroc-001","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["définition"],"difficulty":1,"question":"Au scanner, à partir de quelle taille une opacité pulmonaire intraparenchymateuse est-elle appelée « masse » et non plus « nodule » ?","answer":"3 cm (30 mm)","accept":["3 cm","30 mm","3cm","30mm"],"keywords":["3 cm"],"explanation":"Micronodule < 3 mm, nodule de 3 à 30 mm, masse > 3 cm : la taille est appréciée au scanner.","src":"p. 151-152"},{"id":"p207-qroc-002","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["définition"],"difficulty":1,"question":"Quelle taille limite sépare le micronodule du nodule pulmonaire ?","answer":"3 mm","accept":["3 mm","3mm","trois mm","3 millimètres"],"keywords":["3 mm"],"explanation":"Micronodule < 3 mm ; nodule de 3 à 30 mm ; masse > 3 cm.","src":"p. 152"},{"id":"p207-qroc-003","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["définition","imagerie"],"difficulty":1,"question":"Quels sont les trois types de densité que peut présenter une opacité nodulaire au scanner ?","answer":"Solide, verre dépoli pur, mixte","accept":["solide, verre dépoli et mixte","solide, verre dépoli, mixte"],"keywords":["solide","verre","mixte"],"explanation":"Les opacités intraparenchymateuses, uniques ou multiples, sont de densité solide, en verre dépoli pur ou mixtes (une composante solide et une composante en verre dépoli).","src":"p. 152, 155"},{"id":"p207-qroc-004","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["imagerie"],"difficulty":1,"question":"Quel est l'examen d'imagerie clé devant un nodule pulmonaire ?","answer":"Scanner thoracique (TDM)","accept":["scanner","scanner thoracique","TDM thoracique","TDM du thorax","tomodensitométrie"],"keywords":["scan"],"explanation":"Le scanner est l'examen clé ; la radiographie n'est pas adaptée à la découverte ni à la description des nodules et micronodules.","src":"p. 151, 153"},{"id":"p207-qroc-005","type":"QROC","rank":"A","objective":"p207-obj-01","tags":["imagerie","pièges"],"difficulty":1,"question":"Quel examen d'imagerie courant n'est adapté ni à la découverte ni à la description des nodules et micronodules pulmonaires ?","answer":"La radiographie thoracique","accept":["radiographie","radio thoracique","radio du thorax","cliché thoracique"],"keywords":["radio"],"explanation":"La radiographie thoracique ne convient pas pour les nodules et micronodules : c'est le scanner qui est l'examen clé.","src":"p. 153"},{"id":"p207-qroc-006","type":"QROC","rank":"A","objective":"p207-obj-01","tags":["prévention","pièges"],"difficulty":1,"question":"Quelle est la place de la radiographie thoracique dans le dépistage du cancer du poumon ?","answer":"Aucune","accept":["aucune","aucune place","pas de place","nulle"],"keywords":["aucun"],"explanation":"La radiographie n'a aucune place dans le dépistage. Un scanner faiblement dosé, sans injection, a démontré une baisse de la mortalité chez le fumeur éligible, mais aucun dépistage organisé n'était encore recommandé en France (HAS 2016).","src":"p. 153"},{"id":"p207-qroc-007","type":"QROC","rank":"B","objective":"p207-obj-02","tags":["prévention","imagerie"],"difficulty":2,"question":"Quel examen, répété à intervalle régulier chez un fumeur éligible, a démontré une baisse de la mortalité par cancer du poumon ?","answer":"Scanner thoracique faiblement dosé, sans injection","accept":["scanner faiblement dosé","scanner faible dose","scanner low dose","scanner faiblement irradiant"],"keywords":["dose"],"explanation":"Scanner faiblement dosé, sans produit de contraste, tous les 1 à 2 ans selon les cas : la mortalité par cancer baisse de 20 à 25 % dans la population éligible de 50 à 75 ans fumeurs.","src":"p. 153"},{"id":"p207-qroc-008","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["imagerie","diagnostic"],"difficulty":1,"question":"Quel examen d'imagerie apprécie l'activité métabolique d'un nodule pulmonaire et participe à l'estimation de son risque de malignité ?","answer":"TEP-TDM au 18FDG","accept":["TEP","TEP-TDM","TEP-FDG","18FDG","PET scan"],"keywords":["tep"],"explanation":"Une fixation élevée est un argument de haut risque, une fixation faible ou nulle un argument de faible risque ; la TEP n'est jamais formelle.","src":"p. 153-154"},{"id":"p207-qroc-009","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["imagerie","pièges"],"difficulty":2,"question":"Dans quelles deux situations la TEP-FDG d'un nodule pulmonaire peut-elle être faussement négative ?","answer":"Nodule < 1 cm ; nodule en verre dépoli pur","accept":["moins de 1 cm et verre dépoli pur","inférieur à 1 cm et verre dépoli pur"],"keywords":["1 cm","verre"],"explanation":"Les faux négatifs concernent les nodules de taille inférieure à 1 cm et ceux en verre dépoli pur : une TEP négative n'exclut donc pas un cancer.","src":"p. 153"},{"id":"p207-qroc-010","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["imagerie","pièges"],"difficulty":2,"question":"Quels types de processus peuvent donner des faux positifs de la TEP-FDG devant un nodule pulmonaire ?","answer":"Processus inflammatoires granulomateux ou infectieux","accept":["inflammatoire","granulomateux","infectieux","infection"],"keywords":["infect"],"explanation":"En France, les mycobactérioses, les aspergilloses et la sarcoïdose en sont des causes, ainsi que les foyers infectieux chroniques (actinomycose, nocardiose).","src":"p. 153"},{"id":"p207-qroc-011","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["diagnostic"],"difficulty":1,"question":"Quel examen est le seul à pouvoir affirmer la nature cancéreuse d'un nodule pulmonaire ?","answer":"L'examen anatomopathologique (histologie)","accept":["histologie","histologique","anatomopathologie","anatomopathologique","anapath","anatomo-pathologie"],"keywords":["histo"],"explanation":"Aucun argument clinique ou d'imagerie n'est formel : seule l'histologie donne un diagnostic de certitude.","src":"p. 151, 154"},{"id":"p207-qroc-012","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["clinique","étiologie"],"difficulty":1,"question":"Quel facteur de risque est à rechercher en priorité pour estimer la probabilité de cancer devant un nodule pulmonaire ?","answer":"Le tabagisme","accept":["tabagisme","tabac","fumeur","tabagisme actif"],"keywords":["tabag"],"explanation":"La présomption de malignité repose sur le terrain et les facteurs de risque (tabagisme notamment), la taille, la morphologie, la TEP-FDG et l'évolution.","src":"p. 151, 153"},{"id":"p207-qroc-013","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["imagerie","diagnostic"],"difficulty":2,"question":"Quel aspect des contours d'un nodule au scanner est un argument de haut risque de malignité ?","answer":"Contours irréguliers, spiculés","accept":["spiculés","spiculé","spicules","spiculation","irréguliers","irrégulier"],"keywords":["spicul"],"explanation":"Contours irréguliers, spiculés, attirant les structures voisines = haut risque ; contours réguliers = faible risque.","src":"p. 154"},{"id":"p207-qroc-014","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["imagerie","diagnostic"],"difficulty":2,"question":"Quelle localisation lobaire d'un nodule pulmonaire est un argument de haut risque de malignité ?","answer":"Les lobes supérieurs","accept":["lobes supérieurs","lobe supérieur","supérieur","supérieurs"],"keywords":["supérieur"],"explanation":"Localisation lobaire supérieure = haut risque ; en dehors des lobes supérieurs = faible risque.","src":"p. 154"},{"id":"p207-qroc-015","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["imagerie","suivi"],"difficulty":2,"question":"Au bout de combien de temps sans évolution un nodule solide est-il considéré comme à faible risque de malignité ?","answer":"2 ans","accept":["2 ans","2 an","deux ans","2ans"],"keywords":["2 ans"],"explanation":"Une absence d'évolution à 2 ans est un argument de faible risque pour un nodule solide ; la progression en taille ou en volume est au contraire un argument de haut risque.","src":"p. 154"},{"id":"p207-qroc-016","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["imagerie","suivi"],"difficulty":2,"question":"Quelle durée de surveillance sans évolution est requise pour classer un nodule en verre dépoli à faible risque ?","answer":"3 à 5 ans","accept":["3 à 5 ans","3-5 ans","entre 3 et 5 ans","3 et 5 ans"],"keywords":["3","5 ans"],"explanation":"Le délai de stabilité exigé est plus long pour un verre dépoli que pour un nodule solide.","src":"p. 154"},{"id":"p207-qroc-017","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["imagerie","suivi"],"difficulty":1,"question":"Quelle évolution d'un nodule au scanner est un argument de haut risque de malignité ?","answer":"Progression en taille ou en volume","accept":["progression","augmentation","croissance","grossissement"],"keywords":["progress"],"explanation":"Progression en taille ou en volume = haut risque ; disparition ou diminution de taille = faible risque.","src":"p. 154"},{"id":"p207-qroc-018","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["étiologie"],"difficulty":1,"question":"Quel type histologique de cancer bronchopulmonaire primitif est le plus fréquent et se présente le plus souvent comme un nodule pulmonaire solitaire ?","answer":"Adénocarcinome","accept":["adénocarcinome","adénocarcinome pulmonaire","adénocarcinomes"],"keywords":["adénocarcin"],"explanation":"Il survient surtout chez les plus de 50 ans, fumeurs.","src":"p. 155"},{"id":"p207-qroc-019","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["étiologie","imagerie"],"difficulty":2,"question":"Quelle topographie est souvent retrouvée pour les nodules de métastases pulmonaires ?","answer":"Périphérique et bilatérale","accept":["périphérique et bilatérale","périphériques et bilatérales","périphérique et bilatéral","bilatérale et périphérique"],"keywords":["périph","bilat"],"explanation":"Les métastases donnent des opacités rondes, uniques ou multiples, souvent périphériques et bilatérales, à contours réguliers.","src":"p. 155"},{"id":"p207-qroc-020","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["étiologie"],"difficulty":1,"question":"Quelle est la tumeur bénigne la plus fréquente parmi les nodules pulmonaires ?","answer":"Hamartochondrome","accept":["hamartochondrome","hamartochondromes","hamartome"],"keywords":["hamart"],"explanation":"Les tumeurs bénignes se présentent comme une opacité unique, sphérique, à contour régulier, et représentent environ 1/10 des nodules thoraciques.","src":"p. 156"},{"id":"p207-qroc-021","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["imagerie","étiologie"],"difficulty":2,"question":"Quel aspect scanographique pathognomonique permet de reconnaître la tumeur bénigne pulmonaire la plus fréquente ?","answer":"Aspect en « pop-corn » (calcifications + graisse)","accept":["pop corn","popcorn","pop-corn","en pop-corn","calcifications et densités graisseuses"],"keywords":["pop"],"explanation":"Des calcifications associées à des densités graisseuses donnent l'aspect en pop-corn de l'hamartochondrome.","src":"p. 156"},{"id":"p207-qroc-022","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["imagerie","étiologie"],"difficulty":2,"question":"Que traduit le plus souvent un nodule pulmonaire entièrement calcifié ?","answer":"Une évolution cicatricielle d'une lésion post-infectieuse","accept":["cicatrice","cicatriciel","cicatricielle","séquelle post-infectieuse","lésion post-infectieuse"],"keywords":["cicatri"],"explanation":"Une calcification complète, centrale ou lamellaire/périphérique est en faveur de la bénignité du nodule.","src":"p. 156"},{"id":"p207-qroc-023","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["clinique","étiologie"],"difficulty":2,"question":"Quel contexte clinique permet de distinguer facilement un abcès du poumon à pyogène d'une tumeur ?","answer":"Contexte aigu fébrile","accept":["aigu fébrile","contexte fébrile","fébrile","fièvre"],"keywords":["fébri"],"explanation":"L'abcès survient dans un contexte aigu fébrile et s'excave rapidement, en même temps qu'une vomique.","src":"p. 157"},{"id":"p207-qroc-024","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["diagnostic","paraclinique"],"difficulty":2,"question":"Quel principe guide le choix des examens pour obtenir la preuve histologique d'un nodule pulmonaire ?","answer":"Les moins invasifs et les moins à risque d'abord","accept":["moins invasif","moins invasifs","le moins invasif","peu invasif","moins à risque"],"keywords":["invasi"],"explanation":"On priorise les examens les moins invasifs et les moins à risque, d'où l'examen clinique attentif à la recherche d'une lésion accessible avant tout prélèvement thoracique.","src":"p. 160"},{"id":"p207-qroc-025","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["clinique","paraclinique"],"difficulty":2,"question":"Quelle lésion accessible faut-il chercher à l'examen clinique avant de prélever un nodule pulmonaire, car elle permettrait un prélèvement peu invasif ?","answer":"Une adénopathie périphérique ou sus-claviculaire","accept":["adénopathie périphérique","adénopathie sus-claviculaire","ganglion sus-claviculaire","ganglion périphérique","adénopathie susclaviculaire"],"keywords":["périph"],"explanation":"Le principe est de prioriser les examens diagnostiques les moins invasifs et les moins à risque.","src":"p. 160"},{"id":"p207-qroc-026","type":"QROC","rank":"A","objective":"p207-obj-02","tags":["complications"],"difficulty":1,"question":"Quelle complication survient dans 10 à 20 % des ponctions transpariétales d'un nodule pulmonaire ?","answer":"Pneumothorax","accept":["pneumothorax","un pneumothorax"],"keywords":["pneumothorax"],"explanation":"Le risque est plus élevé si le nodule est à distance de la plèvre ou dans un lobe emphysémateux ; il peut être mal toléré en cas d'insuffisance respiratoire, d'où l'intérêt d'une spirométrie préalable.","src":"p. 160"},{"id":"p207-qroc-027","type":"QROC","rank":"B","objective":"p207-obj-02","tags":["traitement"],"difficulty":2,"question":"Après exérèse chirurgicale d'un nodule dont l'analyse extemporanée confirme un cancer primitif du poumon, par quoi faut-il compléter l'intervention ?","answer":"Résection anatomique (lobectomie) avec curage ganglionnaire","accept":["lobectomie avec curage","lobectomie et curage","lobectomie + curage","résection anatomique avec curage"],"keywords":["lobectom","curage"],"explanation":"L'exérèse du nodule seule est insuffisante dès qu'un cancer primitif est confirmé : il faut une résection anatomique (lobectomie le plus souvent) associée à un curage ganglionnaire.","src":"p. 160"},{"id":"p207-qroc-028","type":"QROC","rank":"A","objective":"p207-obj-09","tags":["définition"],"difficulty":1,"question":"En combien de loges le médiastin est-il artificiellement divisé ?","answer":"9 loges","accept":["9","neuf","9 loges","neuf loges"],"keywords":["9"],"explanation":"3 étages (supérieur, moyen, inférieur) × 3 compartiments (antérieur, moyen, postérieur). L'orientation étiologique repose sur la localisation précise de la lésion dans ces loges.","src":"p. 151, 162-163"},{"id":"p207-qroc-029","type":"QROC","rank":"A","objective":"p207-obj-07","tags":["imagerie"],"difficulty":1,"question":"Comment nomme-t-on le signe radiographique, de valeur localisatrice majeure, qui repose sur l'effacement (ou non) des bords du médiastin par une masse ?","answer":"Signe de la silhouette","accept":["signe de la silhouette","silhouette"],"keywords":["silhouette"],"explanation":"Une masse située en avant du médiastin en efface les bords, et inversement : ce signe permet de localiser la masse.","src":"p. 163"},{"id":"p207-qroc-030","type":"QROC","rank":"A","objective":"p207-obj-07","tags":["imagerie","diagnostic"],"difficulty":1,"question":"Quel examen d'imagerie est l'examen clé pour une masse du médiastin antérieur ou moyen ?","answer":"Scanner thoracique (TDM)","accept":["scanner","scanner thoracique","TDM thoracique","TDM du thorax","tomodensitométrie"],"keywords":["scan"],"explanation":"Le scanner, avec injection de produit de contraste, détermine les densités (tissulaire, graisseuse, liquidienne) et distingue les structures vasculaires normales d'une structure tissulaire ou d'une pathologie vasculaire (anévrysme).","src":"p. 151, 163"},{"id":"p207-qroc-031","type":"QROC","rank":"A","objective":"p207-obj-07","tags":["imagerie"],"difficulty":1,"question":"Quel examen d'imagerie complète le scanner pour le bilan d'une masse du médiastin postérieur ?","answer":"IRM","accept":["IRM","imagerie par résonance magnétique"],"keywords":["irm"],"explanation":"L'IRM est l'examen essentiel du bilan lésionnel des tumeurs du médiastin postérieur : elle permet de reconnaître les lésions infiltrantes.","src":"p. 151, 168"},{"id":"p207-qroc-032","type":"QROC","rank":"A","objective":"p207-obj-07","tags":["diagnostic"],"difficulty":2,"question":"Quelles lésions médiastinales typiques ne nécessitent pas de confirmation histologique ?","answer":"Goitres et kystes","accept":["goitres et kystes","goitre et kyste","goitre, kyste","goitre kyste"],"keywords":["goitre","kyste"],"explanation":"Goitre plongeant, kystes bronchogéniques ou pleuro-péricardiques : l'aspect scanographique typique d'une lésion bénigne suffit à la décision thérapeutique.","src":"p. 151, 169"},{"id":"p207-qroc-033","type":"QROC","rank":"A","objective":"p207-obj-09","tags":["étiologie"],"difficulty":1,"question":"Quelle est l'étiologie principale d'une opacité du médiastin antérieur et supérieur de découverte fortuite ?","answer":"Goitre plongeant","accept":["goitre plongeant","goitre","goitre thyroïdien","goitres plongeants"],"keywords":["goitre"],"explanation":"Tumeur en général bénigne développée à partir d'un lobe thyroïdien et plongeant dans le défilé cervico-thoracique ; elle peut refouler, plus rarement comprimer la trachée.","src":"p. 163"},{"id":"p207-qroc-034","type":"QROC","rank":"A","objective":"p207-obj-09","tags":["imagerie","diagnostic"],"difficulty":2,"question":"Quel signe au scanner permet d'affirmer qu'une masse du médiastin antérieur et supérieur est d'origine thyroïdienne ?","answer":"Continuité de la masse avec la glande thyroïde","accept":["continuité avec la thyroïde","continuité avec la glande thyroïde","continuité thyroïdienne","en continuité avec la thyroïde"],"keywords":["continuit"],"explanation":"Le scanner montre la lésion en continuité avec la glande thyroïde, souvent calcifiée.","src":"p. 163"},{"id":"p207-qroc-035","type":"QROC","rank":"A","objective":"p207-obj-09","tags":["étiologie"],"difficulty":1,"question":"Quelle est l'étiologie la plus fréquente des opacités du médiastin moyen ?","answer":"Les adénopathies médiastinales","accept":["adénopathies","adénopathie","adénopathies médiastinales","ganglions médiastinaux"],"keywords":["adénopath"],"explanation":"Elles sont tumorales (cancers bronchopulmonaires, lymphomes, métastases ganglionnaires) ou non tumorales (sarcoïdose, tuberculose, silicose...).","src":"p. 167"},{"id":"p207-qroc-036","type":"QROC","rank":"A","objective":"p207-obj-09","tags":["étiologie","imagerie"],"difficulty":1,"question":"Comment appelle-t-on une masse régulière, arrondie, de contenu liquidien, au contact de l'arbre bronchique, située dans le médiastin moyen ?","answer":"Kyste bronchogénique","accept":["kyste bronchogénique","kystes bronchogéniques","bronchogénique"],"keywords":["bronchogén"],"explanation":"Sa tonalité hydrique à la TDM ne laisse pas de doute sur sa nature kystique.","src":"p. 167"},{"id":"p207-qroc-037","type":"QROC","rank":"A","objective":"p207-obj-09","tags":["étiologie"],"difficulty":1,"question":"Quels kystes siègent dans l'angle cardio-phrénique, au niveau du médiastin antérieur et inférieur ?","answer":"Kystes pleuro-péricardiques","accept":["kyste pleuro-péricardique","kystes pleuropéricardiques","pleuro-péricardique","pleuropéricardique"],"keywords":["péricard"],"explanation":"Ce sont des tumeurs liquidiennes de l'angle cardio-phrénique, le plus souvent asymptomatiques.","src":"p. 166"},{"id":"p207-qroc-038","type":"QROC","rank":"A","objective":"p207-obj-09","tags":["étiologie"],"difficulty":1,"question":"Quelles tumeurs sont typiquement retrouvées dans le médiastin postérieur ?","answer":"Les tumeurs neurogènes","accept":["tumeurs neurogènes","tumeur neurogène","neurogène","neurogènes"],"keywords":["neurogèn"],"explanation":"Elles représentent 1/3 des tumeurs du médiastin ; le plus souvent bénignes chez l'adulte, malignes chez l'enfant. L'IRM est l'examen essentiel de leur bilan.","src":"p. 168"},{"id":"p207-qroc-039","type":"QROC","rank":"A","objective":"p207-obj-07","tags":["biologie","diagnostic"],"difficulty":2,"question":"Quels deux dosages sanguins faut-il demander devant une tumeur du médiastin antérieur ?","answer":"Alpha-fœtoprotéine et HCG","accept":["AFP et HCG","alpha-fœtoprotéine et HCG","AFP + HCG","AFP et bêta-HCG","alpha-fœtoprotéine et bêta-HCG"],"keywords":["fœto","hcg"],"explanation":"Ce dosage fait partie des moyens de la preuve histologique cités pour les tumeurs du médiastin antérieur, avec la ponction transpariétale, la courte médiastinotomie antérieure et la chirurgie diagnostique et d'exérèse.","src":"p. 168"},{"id":"p207-qroc-040","type":"QROC","rank":"B","objective":"p207-obj-09","tags":["urgence","diagnostic"],"difficulty":3,"question":"Chez un homme jeune en urgence vitale par compression médiastinale aiguë d'une masse volumineuse, quel élément biologique suffit à porter le diagnostic de tumeur germinale non séminomateuse, sans preuve histologique ?","answer":"Élévation franche de l'alpha-fœtoprotéine ou de l'HCG","accept":["élévation franche de l'AFP ou de l'HCG","AFP ou HCG","AFP et HCG","élévation de l'AFP ou de l'HCG"],"keywords":["fœto","hcg"],"explanation":"Le diagnostic de TGNS peut être porté sur la seule élévation franche de l'alpha-fœtoprotéine ou de l'HCG ; si ces marqueurs sont négatifs, un abord histologique est nécessaire.","src":"p. 169-170"},{"id":"p207-qroc-041","type":"QROC","rank":"B","objective":"p207-obj-09","tags":["étiologie"],"difficulty":1,"question":"Quelle maladie, liée à des anticorps anti-récepteurs de l'acétylcholine, peut révéler une tumeur épithéliale du thymus ?","answer":"Myasthénie","accept":["myasthénie","la myasthénie"],"keywords":["myasthén"],"explanation":"Une tumeur épithéliale du thymus peut être découverte à l'occasion d'une myasthénie, due à la production d'anticorps anti-récepteurs de l'acétylcholine par la tumeur.","src":"p. 164"},{"id":"p207-qroc-042","type":"QROC","rank":"B","objective":"p207-obj-07","tags":["paraclinique"],"difficulty":2,"question":"Quel est l'examen de référence pour le diagnostic des adénopathies médiastinales ?","answer":"Médiastinoscopie","accept":["médiastinoscopie","la médiastinoscopie"],"keywords":["médiastinoscop"],"explanation":"Sensibilité et spécificité de l'ordre de 100 %, mais elle n'est performante que pour les adénopathies axiales (autour de la trachée) et hautes, pas plus bas que la région précarinaire ; la ponction transbronchique échoguidée (EBUS) tend à la remplacer en première intention.","src":"p. 168"},{"id":"p207-qcm-101","type":"QRM","rank":"A","objective":"p207-obj-02","tags":["définition"],"difficulty":1,"stem":"Quelle(s) proposition(s) est (sont) exacte(s) à propos des opacités pulmonaires intraparenchymateuses mesurées au scanner ?","options":[{"t":"Un micronodule mesure moins de 3 mm.","ok":true,"why":"Micronodule < 3 mm ; nodule de 3 à 30 mm ; masse > 3 cm."},{"t":"Un nodule est par définition une opacité unique.","ok":false,"why":"Les opacités intraparenchymateuses peuvent être uniques ou multiples."},{"t":"Un nodule mesure entre 1 et 5 cm.","ok":false,"why":"Le nodule mesure de 3 à 30 mm ; au-delà de 3 cm, il s'agit d'une masse."},{"t":"Une opacité de 40 mm est un nodule de grande taille.","ok":false,"why":"Au-delà de 3 cm (30 mm), on parle de masse et non plus de nodule."},{"t":"Un micronodule mesure moins de 1 cm.","ok":false,"why":"Le seuil du micronodule est de 3 mm."}],"explanation":"Micronodule < 3 mm, nodule de 3 à 30 mm, masse > 3 cm ; les opacités peuvent être uniques ou multiples, solides, en verre dépoli pur ou mixtes.","src":"p. 151-152"},{"id":"p207-qcm-102","type":"QRM","rank":"A","objective":"p207-obj-02","tags":["diagnostic","prévention"],"difficulty":2,"stem":"À propos de la découverte et du dépistage des nodules pulmonaires, quelles sont les propositions exactes ?","options":[{"t":"Le scanner de dépistage du cancer du poumon doit être réalisé avec injection de produit de contraste.","ok":false,"why":"Le scanner de dépistage est faiblement dosé et sans injection."},{"t":"La radiographie thoracique est inadaptée à la découverte des nodules et micronodules.","ok":true,"why":"Le scanner est l'examen clé ; la radiographie ne convient ni à la découverte ni à la description des nodules."},{"t":"La radiographie thoracique répétée a sa place dans le dépistage du cancer du poumon chez le gros fumeur.","ok":false,"why":"La radiographie n'a aucune place dans le dépistage du cancer pulmonaire."},{"t":"Un dépistage organisé du cancer du poumon par scanner est déjà recommandé en France depuis 2016.","ok":false,"why":"Il n'existait pas encore de recommandation de dépistage organisé en France (HAS 2016) ; seuls des programmes pilotes étaient en cours."},{"t":"Un scanner faiblement dosé, sans injection, réduit la mortalité par cancer chez les fumeurs éligibles.","ok":true,"why":"La baisse de mortalité par cancer est de 20 à 25 % chez les sujets de 50 à 75 ans fumeurs ou ex-fumeurs."}],"explanation":"La radiographie est inadaptée aux nodules et n'a aucune place dans le dépistage ; le scanner faiblement dosé sans injection a démontré une baisse de mortalité, mais aucun dépistage organisé n'était encore recommandé en France.","trap":"Radiographie thoracique et dépistage : aucune place.","src":"p. 153"},{"id":"p207-qcm-103","type":"QRM","rank":"A","objective":"p207-obj-02","tags":["diagnostic","imagerie"],"difficulty":2,"stem":"Un homme de 68 ans, fumeur, a un nodule solide de 24 mm du lobe supérieur droit, aux contours spiculés, dont le volume a augmenté entre deux scanners. Quels éléments sont des arguments en faveur de la malignité ?","options":[{"t":"La taille de 24 mm, supérieure au seuil au-delà duquel la malignité est certaine.","ok":false,"why":"Il n'existe pas de valeur seuil de taille et aucun argument n'est formel : seule l'histologie permet un diagnostic de certitude."},{"t":"Les contours spiculés.","ok":true,"why":"Des contours irréguliers, spiculés, attirant les structures voisines indiquent un haut risque."},{"t":"La localisation dans un lobe supérieur.","ok":true,"why":"La localisation lobaire supérieure fait partie des critères de haut risque."},{"t":"Une absence de fixation en TEP-FDG permettrait d'exclure le diagnostic de cancer.","ok":false,"why":"Une fixation faible ou nulle est rassurante mais pas formelle (faux négatifs possibles, seule l'histologie permet la certitude)."},{"t":"L'augmentation de volume entre les deux scanners.","ok":true,"why":"La progression en taille ou en volume est un argument de haut risque."}],"explanation":"Tabagisme, âge élevé, contours spiculés, localisation lobaire supérieure, fixation élevée en TEP et progression en taille ou en volume sont des arguments de malignité, mais aucun n'est formel : seule l'histologie affirme le cancer.","src":"p. 151, 154"},{"id":"p207-qcm-104","type":"QRM","rank":"A","objective":"p207-obj-02","tags":["diagnostic","imagerie"],"difficulty":2,"stem":"Concernant les arguments en faveur de la bénignité d'un nodule pulmonaire, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Un nodule solide stable pendant 6 mois est classé à faible risque de malignité.","ok":false,"why":"Le délai d'absence d'évolution retenu pour un nodule solide est de 2 ans."},{"t":"Un nodule en verre dépoli stable pendant 2 ans est classé à faible risque de malignité.","ok":false,"why":"Pour un verre dépoli, il faut une absence d'évolution de 3 à 5 ans."},{"t":"Un nodule triangulaire homogène de 25 mm, à 5 mm de la plèvre, évoque un ganglion intrapulmonaire.","ok":false,"why":"Le ganglion intrapulmonaire mesure moins de 10 mm (à moins de 15 mm de la plèvre, sous le niveau de la carène)."},{"t":"Une fixation élevée en TEP-FDG est un argument de faible risque.","ok":false,"why":"Fixation élevée = haut risque ; fixation faible ou nulle = faible risque."},{"t":"Un nodule entièrement calcifié est le plus souvent la cicatrice d'une lésion post-infectieuse.","ok":true,"why":"Une calcification complète, centrale ou lamellaire/périphérique est en faveur de la bénignité."}],"explanation":"Les calcifications (complète, centrale, lamellaire ou périphérique) et la stabilité prolongée (2 ans pour un solide, 3 à 5 ans pour un verre dépoli) sont des arguments de bénignité.","src":"p. 154, 156"},{"id":"p207-qcm-105","type":"QRM","rank":"A","objective":"p207-obj-02","tags":["imagerie","pièges"],"difficulty":2,"stem":"Un nodule pulmonaire de 8 mm ne fixe pas en TEP-TDM au 18FDG. Quelles propositions sont exactes ?","options":[{"t":"Cette absence de fixation affirme la bénignité du nodule.","ok":false,"why":"Aucun argument n'est formel : seule l'histologie permet un diagnostic de certitude."},{"t":"Une taille inférieure à 1 cm expose à un faux négatif de la TEP.","ok":true,"why":"Des faux négatifs sont possibles lorsque le nodule mesure moins de 1 cm."},{"t":"Une fixation élevée aurait suffi à affirmer le cancer.","ok":false,"why":"Une fixation positive donne un rapport de vraisemblance de l'ordre de 4 en faveur du cancer : elle l'oriente sans l'affirmer."},{"t":"Un nodule en verre dépoli pur peut aussi être faussement négatif.","ok":true,"why":"Le verre dépoli pur est l'autre situation de faux négatif de la TEP-FDG."},{"t":"Les faux positifs de la TEP-FDG sont uniquement dus à des tumeurs bénignes.","ok":false,"why":"Ils sont dus à des processus inflammatoires granulomateux ou infectieux (mycobactérioses, aspergilloses, sarcoïdose)."}],"explanation":"Une TEP négative n'exclut pas un cancer devant un nodule de moins de 1 cm ou en verre dépoli pur.","trap":"TEP négative ≠ nodule bénin.","src":"p. 153-154"},{"id":"p207-qcm-106","type":"QRM","rank":"B","objective":"p207-obj-02","tags":["étiologie"],"difficulty":2,"stem":"Parmi les lésions suivantes, laquelle (lesquelles) fait (font) partie des causes non tumorales de nodule pulmonaire ?","options":[{"t":"Tuberculome","ok":true,"why":"Avec l'abcès, l'aspergillome, le kyste hydatique, les nodules rhumatoïdes ou la GPA, il fait partie des opacités non tumorales."},{"t":"Hamartochondrome","ok":false,"why":"C'est la tumeur bénigne la plus fréquente : il s'agit d'une tumeur."},{"t":"Carcinoïde bronchique","ok":false,"why":"Il est classé avec les cancers bronchopulmonaires primitifs (tumeurs malignes)."},{"t":"Métastase d'un cancer du rein","ok":false,"why":"Les tumeurs secondaires sont des tumeurs malignes."},{"t":"Ganglion intrapulmonaire","ok":false,"why":"Le Collège le classe parmi les tumeurs bénignes, avec l'hamartochondrome."}],"explanation":"Les opacités non tumorales regroupent notamment la GPA, les nodules rhumatoïdes, le kyste hydatique, l'aspergillome, l'abcès, le tuberculome, l'atélectasie ronde, les masses silicotiques et les lésions vasculaires.","src":"p. 159"},{"id":"p207-qcm-107","type":"QRM","rank":"B","objective":"p207-obj-02","tags":["étiologie","diagnostic"],"difficulty":2,"stem":"À propos des nodules d'origine infectieuse, quelles propositions sont exactes ?","options":[{"t":"Un tuberculome correspond toujours à un foyer tuberculeux actif.","ok":false,"why":"Il peut être quiescent, cicatriciel ou représenter un foyer encore actif."},{"t":"Un abcès à pyogène se distingue d'une tumeur par un contexte aigu fébrile et une excavation rapide avec vomique.","ok":true,"why":"C'est ce contexte qui permet de le différencier facilement d'une affection tumorale."},{"t":"Le kyste hydatique donne une opacité de contenu solide homogène, sans composante liquidienne.","ok":false,"why":"Son contenu est liquidien, avec parfois un aspect de membrane flottante surmontée d'un croissant gazeux."},{"t":"Un tuberculome justifie des prélèvements mycobactériologiques dirigés si la tuberculose n'était pas connue ni traitée.","ok":true,"why":"Il peut représenter un foyer actif : on cherche la preuve mycobactériologique."},{"t":"Une infection à Actinomyces ou à Nocardia peut être difficile à différencier d'un cancer en TDM comme en TEP-FDG.","ok":true,"why":"Ces bactéries filamenteuses à croissance lente rendent le diagnostic beaucoup plus difficile."}],"explanation":"L'abcès à pyogène est facile à distinguer d'une tumeur ; les infections à bactéries filamenteuses et les tuberculomes sont plus trompeurs.","src":"p. 157"},{"id":"p207-qcm-108","type":"QRM","rank":"A","objective":"p207-obj-02","tags":["diagnostic","paraclinique"],"difficulty":2,"stem":"Concernant la démarche pour obtenir la preuve histologique d'un nodule pulmonaire suspect, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"L'endoscopie bronchique permet d'atteindre les lésions distales sans instrument particulier.","ok":false,"why":"Elle n'explore que les bronches centrales, sauf avec des instruments spécifiques (échographie radiale par exemple)."},{"t":"On priorise les examens les moins invasifs et les moins à risque.","ok":true,"why":"D'où l'examen clinique attentif à la recherche d'une adénopathie périphérique ou sus-claviculaire accessible."},{"t":"La biopsie sous échographie est possible pour tout nodule, quelle que soit sa situation dans le poumon.","ok":false,"why":"Elle n'est possible que pour les lésions au contact de la plèvre, dans des centres spécialisés."},{"t":"L'endoscopie bronchique n'a plus d'indication depuis que le scanner permet de localiser les lésions.","ok":false,"why":"Elle reste d'indication large pour rechercher une autre lésion plus proximale."},{"t":"L'exérèse chirurgicale d'emblée est toujours préférable à un prélèvement moins invasif.","ok":false,"why":"Le principe est de commencer par les examens diagnostiques les moins invasifs."}],"explanation":"On commence par l'examen clinique (lésion accessible), puis par les techniques les moins invasives, en tenant compte de la localisation du nodule et de la fonction respiratoire.","src":"p. 160-161"},{"id":"p207-qcm-109","type":"QRM","rank":"A","objective":"p207-obj-02","tags":["complications"],"difficulty":1,"stem":"Concernant la ponction transpariétale d'un nodule pulmonaire sous contrôle scanographique, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Elle se complique d'un pneumothorax dans 10 à 20 % des cas.","ok":true,"why":"Complication fréquente, notamment si le nodule est à distance de la plèvre ou dans un lobe emphysémateux."},{"t":"Le risque de pneumothorax est diminué si le nodule siège dans un lobe emphysémateux.","ok":false,"why":"L'emphysème et l'éloignement du nodule par rapport à la plèvre augmentent le risque."},{"t":"Elle dispense de toute évaluation de la fonction respiratoire.","ok":false,"why":"Une évaluation spirométrique préalable est raisonnable, car un pneumothorax peut être mal toléré en cas d'insuffisance respiratoire."},{"t":"Un pneumothorax est toujours bien toléré, même chez le patient insuffisant respiratoire.","ok":false,"why":"Cette complication peut être mal tolérée en cas d'insuffisance respiratoire."},{"t":"Elle ne peut être réalisée que sous contrôle échographique.","ok":false,"why":"Elle se fait sous contrôle TDM, voire échographique ; la biopsie sous échographie est réservée aux lésions au contact de la plèvre."}],"explanation":"Le pneumothorax complique 10 à 20 % des ponctions transpariétales, avec un risque majoré par l'éloignement de la plèvre et l'emphysème.","src":"p. 160"},{"id":"p207-qcm-110","type":"QRM","rank":"A","objective":"p207-obj-09","tags":["définition","imagerie"],"difficulty":2,"stem":"À propos de l'anatomie du médiastin, quelles propositions sont exactes ?","options":[{"t":"Il est limité en arrière par le sternum.","ok":false,"why":"En avant : la paroi thoracique (sternum) ; en arrière : les vertèbres."},{"t":"Il est artificiellement divisé en 9 loges.","ok":true,"why":"3 étages (supérieur, moyen, inférieur) × 3 compartiments (antérieur, moyen, postérieur)."},{"t":"Le compartiment postérieur est situé en avant de l'axe trachéo-bronchique.","ok":false,"why":"Le compartiment postérieur est situé en arrière de l'axe trachéo-bronchique."},{"t":"L'étage moyen est situé entre l'aorte et la carène.","ok":true,"why":"L'étage supérieur est au-dessus de la portion horizontale de la crosse aortique ; l'étage inférieur est sous la carène."},{"t":"Il est limité latéralement par les plèvres médiastinales droite et gauche.","ok":true,"why":"Ses limites : défilé cervico-thoracique en haut, diaphragme en bas, paroi thoracique en avant, vertèbres en arrière."}],"explanation":"La localisation précise de la lésion dans l'une des 9 loges est la base de l'orientation étiologique d'une masse médiastinale.","src":"p. 151, 162-163"},{"id":"p207-qcm-111","type":"QRM","rank":"B","objective":"p207-obj-07","tags":["imagerie","diagnostic"],"difficulty":2,"stem":"Quels aspects sur une radiographie de thorax sont en faveur d'une masse médiastinale ?","options":[{"t":"Une tonalité aérique, plus claire que le reste du médiastin.","ok":false,"why":"La tonalité est hydrique, comme celle du reste du médiastin."},{"t":"Une limite externe nette, convexe vers le poumon.","ok":true,"why":"C'est l'aspect habituel de la limite externe d'une masse médiastinale."},{"t":"Une limite interne nettement visible au sein du médiastin.","ok":false,"why":"La limite interne n'est pas visible : elle est indiscernable des éléments du médiastin."},{"t":"Un raccordement en pente douce avec le médiastin.","ok":true,"why":"L'opacité se raccorde en pente douce avec le médiastin."},{"t":"Une limite interne non discernable des éléments du médiastin.","ok":true,"why":"La limite interne n'est pas visible car elle se confond avec les structures médiastinales."}],"explanation":"Opacité à limite externe nette et convexe, raccordée en pente douce, sans limite interne visible, de tonalité hydrique ; la déformation ou le déplacement d'une ligne médiastinale (signe de la silhouette) a une valeur localisatrice majeure.","src":"p. 163"},{"id":"p207-qcm-112","type":"QRM","rank":"B","objective":"p207-obj-09","tags":["étiologie"],"difficulty":2,"stem":"Concernant les tumeurs thymiques, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Une augmentation de taille du thymus est pathologique dès l'âge de 20 ans.","ok":false,"why":"Elle n'est considérée comme pathologique qu'après l'âge de 40 ans."},{"t":"Elles siègent dans le médiastin postérieur.","ok":false,"why":"Elles siègent dans le médiastin antérieur et moyen."},{"t":"Le thymus persiste à l'âge adulte sous la forme d'une glande de taille normale.","ok":false,"why":"Il subit une involution adipeuse : la glande disparaît à l'âge adulte et laisse un reliquat graisseux rétrosternal."},{"t":"Les tumeurs épithéliales du thymus produisent des anticorps anti-récepteurs de la TSH.","ok":false,"why":"Les anticorps cités sont des anticorps anti-récepteurs de l'acétylcholine, responsables d'une myasthénie."},{"t":"Elles comprennent des tumeurs épithéliales, des lymphomes et des kystes.","ok":true,"why":"Trois catégories : tumeurs épithéliales (parfois révélées par une myasthénie), lymphomes thymiques, kystes et tumeurs bénignes."}],"explanation":"Les tumeurs thymiques comprennent les tumeurs épithéliales (parfois révélées par une myasthénie), les lymphomes thymiques, les kystes et tumeurs bénignes.","src":"p. 164"},{"id":"p207-qcm-113","type":"QRM","rank":"A","objective":"p207-obj-09","tags":["étiologie"],"difficulty":1,"stem":"Quelle(s) lésion(s) se développe(nt) habituellement dans le médiastin moyen ?","options":[{"t":"Goitre plongeant","ok":false,"why":"Il siège dans le médiastin antérieur et supérieur."},{"t":"Schwannome","ok":false,"why":"Les tumeurs neurogènes siègent dans le médiastin postérieur."},{"t":"Kyste bronchogénique","ok":true,"why":"Masse régulière, arrondie, de contenu liquidien, au contact de l'arbre bronchique ; les adénopathies restent l'étiologie la plus fréquente du médiastin moyen."},{"t":"Neurofibrome","ok":false,"why":"C'est une tumeur neurogène, donc du médiastin postérieur."},{"t":"Kyste pleuro-péricardique","ok":false,"why":"Il siège dans l'angle cardio-phrénique, au niveau du médiastin antérieur et inférieur."}],"explanation":"Dans le médiastin moyen dominent les adénopathies, loin devant les kystes bronchogéniques.","src":"p. 166-167"},{"id":"p207-qcm-114","type":"QRM","rank":"B","objective":"p207-obj-09","tags":["étiologie"],"difficulty":2,"stem":"Parmi les causes d'adénopathies médiastinales suivantes, laquelle (lesquelles) est (sont) d'origine tumorale ?","options":[{"t":"Sarcoïdose","ok":false,"why":"Cause non tumorale d'adénopathies médiastinales."},{"t":"Lymphome","ok":true,"why":"Lymphome (hodgkinien ou non) et leucémie lymphoïde chronique sont des causes tumorales."},{"t":"Silicose","ok":false,"why":"Cause non tumorale d'adénopathies médiastinales."},{"t":"Histoplasmose","ok":false,"why":"Cause infectieuse non tumorale (Amérique du Nord)."},{"t":"Tuberculose","ok":false,"why":"Cause infectieuse non tumorale d'adénopathies médiastinales."}],"explanation":"Adénopathies tumorales : cancers bronchopulmonaires, lymphomes ou leucémie lymphoïde chronique, métastases ganglionnaires de cancers extrathoraciques.","src":"p. 167"},{"id":"p207-qcm-115","type":"QRM","rank":"B","objective":"p207-obj-07","tags":["diagnostic","paraclinique"],"difficulty":2,"stem":"Un homme de 28 ans a une volumineuse tumeur du médiastin antérieur. Quels moyens participent à la preuve histologique ou au diagnostic ?","options":[{"t":"Une ponction trans-œsophagienne à l'aiguille sous échoendoscopie.","ok":false,"why":"Ce moyen est cité pour les tumeurs du médiastin postérieur."},{"t":"Le dosage de l'alpha-fœtoprotéine et de l'HCG.","ok":true,"why":"Premier moyen cité pour les tumeurs du médiastin antérieur."},{"t":"Une courte médiastinotomie antérieure, dans le 2e espace intercostal.","ok":true,"why":"Abord à visée diagnostique cité pour les tumeurs du médiastin antérieur."},{"t":"Une médiastinoscopie, examen de référence des tumeurs du médiastin antérieur.","ok":false,"why":"La médiastinoscopie est l'examen de référence des adénopathies médiastinales (médiastin moyen), pas des tumeurs du médiastin antérieur."},{"t":"Une ponction transpariétale à l'aiguille.","ok":true,"why":"Moyen cité pour les tumeurs du médiastin antérieur comme pour celles du médiastin postérieur."}],"explanation":"Pour le médiastin antérieur : dosage de l'AFP et de l'HCG, ponction transpariétale, courte médiastinotomie antérieure, ou chirurgie diagnostique et d'exérèse si elle peut être complète et peu mutilante.","src":"p. 168"},{"id":"p207-qcm-116","type":"QRM","rank":"A","objective":"p207-obj-09","tags":["diagnostic","pièges"],"difficulty":2,"stem":"Pour quelles lésions médiastinales l'aspect scanographique typique d'une lésion bénigne dispense-t-il de preuve histologique avant la décision thérapeutique ?","options":[{"t":"Adénopathies médiastinales","ok":false,"why":"Elles font partie des cas moins simples : l'aspect oriente vers une tumeur potentiellement maligne, la preuve histologique est nécessaire."},{"t":"Goitre plongeant","ok":true,"why":"C'est un cas simple : aspect typique d'une lésion bénigne."},{"t":"Tératome","ok":false,"why":"Tératomes et tumeurs germinales sont des cas moins simples nécessitant une preuve histologique."},{"t":"Tumeur neurogène de l'adulte","ok":true,"why":"Cas simple chez l'adulte ; chez l'enfant, la preuve histologique est nécessaire."},{"t":"Kyste bronchogénique","ok":true,"why":"Comme le kyste pleuro-péricardique, c'est un cas simple."}],"explanation":"Cas simples (pas de preuve histologique) : goitre plongeant, kystes bronchogéniques ou pleuro-péricardiques, tumeur thymique bien limitée résécable d'emblée, tumeurs neurogènes de l'adulte.","trap":"Tumeur neurogène : simple chez l'adulte, pas chez l'enfant.","src":"p. 169"},{"id":"p207-qcm-117","type":"QRM","rank":"B","objective":"p207-obj-07","tags":["paraclinique"],"difficulty":3,"stem":"À propos de la médiastinoscopie, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Sa sensibilité et sa spécificité sont de l'ordre de 50 %.","ok":false,"why":"Elles sont de l'ordre de 100 %."},{"t":"Elle explore bien les adénopathies de topographie basse, sous la carène.","ok":false,"why":"Elle n'est performante que pour les adénopathies axiales de topographie haute, pas plus bas que la région précarinaire."},{"t":"Elle tend à remplacer la ponction transbronchique échoguidée (EBUS) en première intention.","ok":false,"why":"C'est l'inverse : l'EBUS tend à la remplacer en première intention."},{"t":"Elle est l'examen de référence des tumeurs du médiastin postérieur.","ok":false,"why":"Pour le médiastin postérieur : ponction transpariétale, ponction trans-œsophagienne échoguidée ou chirurgie diagnostique et d'exérèse."},{"t":"Elle est l'examen de référence pour le diagnostic des adénopathies médiastinales.","ok":true,"why":"Sensibilité et spécificité de l'ordre de 100 %, mais performante seulement pour les adénopathies axiales hautes."}],"explanation":"La médiastinoscopie reste l'examen de référence des adénopathies médiastinales, mais l'EBUS la remplace de plus en plus en première intention.","src":"p. 168"},{"id":"p207-qru-101","type":"QRU","rank":"A","objective":"p207-obj-02","tags":["imagerie","diagnostic"],"difficulty":2,"stem":"Quelle est la seule proposition exacte concernant la TEP-TDM au 18FDG devant un nodule pulmonaire ?","options":[{"t":"Une fixation positive oriente vers un cancer (rapport de vraisemblance d'environ 4) sans l'affirmer.","ok":true,"why":"La TEP-FDG a modifié l'arbre décisionnel devant un nodule, mais elle n'est jamais formelle."},{"t":"Elle est très fiable pour éliminer un cancer devant un nodule de moins de 1 cm.","ok":false,"why":"Les faux négatifs sont possibles pour les nodules de moins de 1 cm."},{"t":"Elle dispense de l'examen anatomopathologique en cas de fixation élevée.","ok":false,"why":"Seule l'histologie affirme la nature cancéreuse d'un nodule."},{"t":"Elle ne donne jamais de faux positif, ce qui permet d'affirmer le cancer devant un nodule hypermétabolique.","ok":false,"why":"Des faux positifs existent avec les processus inflammatoires granulomateux ou infectieux."},{"t":"Elle est particulièrement performante pour les nodules en verre dépoli pur.","ok":false,"why":"Le verre dépoli pur expose aux faux négatifs."}],"explanation":"Une TEP positive augmente la probabilité de cancer (rapport de vraisemblance de l'ordre de 4) sans l'affirmer ; faux négatifs sous 1 cm et en verre dépoli pur, faux positifs dans les processus granulomateux ou infectieux.","src":"p. 153"},{"id":"p207-qru-102","type":"QRU","rank":"A","objective":"p207-obj-02","tags":["imagerie","étiologie"],"difficulty":1,"stem":"Un homme de 55 ans a un nodule pulmonaire unique, sphérique, à contours réguliers. Le scanner retrouve des calcifications associées à des densités graisseuses (aspect en « pop-corn »). Quel est le diagnostic le plus probable ?","options":[{"t":"Métastase d'un cancer du côlon","ok":false,"why":"Les métastases donnent des opacités rondes souvent multiples, périphériques et bilatérales, sans aspect en pop-corn."},{"t":"Aspergillome","ok":false,"why":"L'aspergillome donne un aspect « en grelot » au sein d'une cavité préexistante."},{"t":"Adénocarcinome primitif","ok":false,"why":"L'adénocarcinome est typiquement un nodule solide à contours irréguliers, spiculés."},{"t":"Hamartochondrome","ok":true,"why":"Tumeur bénigne la plus fréquente, à aspect scanographique pathognomonique en pop-corn."},{"t":"Kyste hydatique","ok":false,"why":"Le kyste hydatique a un contenu liquidien, avec parfois une membrane flottante surmontée d'un croissant gazeux."}],"explanation":"L'association de calcifications et de densités graisseuses (pop-corn) est pathognomonique de l'hamartochondrome, ce qui rend le diagnostic souvent facile.","src":"p. 156"},{"id":"p207-qru-103","type":"QRU","rank":"B","objective":"p207-obj-02","tags":["traitement"],"difficulty":2,"stem":"L'exérèse chirurgicale d'un nodule suspect avec analyse extemporanée confirme un cancer primitif du poumon. Quelle est la suite du geste opératoire ?","options":[{"t":"Se contenter de l'exérèse du nodule, qui est alors suffisante.","ok":false,"why":"Elle est insuffisante dès que le cancer primitif est confirmé."},{"t":"Compléter par une lobectomie avec curage ganglionnaire.","ok":true,"why":"Résection anatomique (lobectomie le plus souvent) associée à un curage ganglionnaire."},{"t":"Réaliser une simple surveillance par scanner à intervalle régulier.","ok":false,"why":"Un cancer primitif confirmé impose un geste complémentaire, pas une simple surveillance."},{"t":"Réaliser une biopsie transpariétale pour confirmer le diagnostic.","ok":false,"why":"Le diagnostic est déjà confirmé par l'analyse extemporanée de la pièce d'exérèse."},{"t":"Prescrire une nouvelle TEP-TDM avant toute décision.","ok":false,"why":"La confirmation histologique est obtenue : un geste complémentaire doit compléter l'intervention."}],"explanation":"Si le cancer primitif est confirmé à l'extemporanée, l'exérèse du nodule est complétée par une résection anatomique (lobectomie le plus souvent) et un curage ganglionnaire.","src":"p. 160"},{"id":"p207-qru-104","type":"QRU","rank":"A","objective":"p207-obj-02","tags":["clinique","étiologie"],"difficulty":1,"stem":"Un homme de 45 ans présente depuis 5 jours une fièvre élevée et une toux. Il rapporte une vomique et le scanner montre une opacité qui s'est excavée en quelques jours. Quel est le diagnostic le plus probable ?","options":[{"t":"Adénocarcinome primitif du poumon","ok":false,"why":"Une tumeur ne survient pas dans un contexte aigu fébrile avec excavation rapide."},{"t":"Hamartochondrome","ok":false,"why":"Tumeur bénigne à aspect en pop-corn, sans contexte fébrile."},{"t":"Aspergillome sur cavité préexistante","ok":false,"why":"Il se développe dans une cavité préexistante, avec un aspect en grelot."},{"t":"Métastase pulmonaire unique","ok":false,"why":"Opacités rondes souvent multiples, périphériques, bilatérales, sans contexte fébrile aigu."},{"t":"Abcès à pyogène","ok":true,"why":"Contexte aigu fébrile, excavation rapide, vomique : tableau typique."}],"explanation":"L'abcès à pyogène se distingue facilement d'une tumeur par son contexte aigu fébrile et son excavation rapide avec vomique.","src":"p. 157"},{"id":"p207-qru-105","type":"QRU","rank":"A","objective":"p207-obj-07","tags":["imagerie","diagnostic"],"difficulty":1,"stem":"Un scanner thoracique découvre une masse paravertébrale du médiastin postérieur chez un adulte. Quel examen est essentiel pour compléter le bilan lésionnel et reconnaître les lésions infiltrantes ?","options":[{"t":"Dosage de l'alpha-fœtoprotéine et de l'HCG","ok":false,"why":"Ce dosage est cité pour les tumeurs du médiastin antérieur."},{"t":"Médiastinoscopie","ok":false,"why":"Examen de référence des adénopathies médiastinales (médiastin moyen)."},{"t":"IRM thoracique","ok":true,"why":"Examen essentiel du bilan lésionnel des tumeurs du médiastin postérieur."},{"t":"Courte médiastinotomie antérieure","ok":false,"why":"Abord cité pour les tumeurs du médiastin antérieur."},{"t":"Ponction transbronchique échoguidée (EBUS)","ok":false,"why":"Elle tend à remplacer la médiastinoscopie pour les adénopathies du médiastin moyen."}],"explanation":"Le scanner est complété par l'IRM pour les masses du médiastin postérieur, notamment les tumeurs neurogènes.","src":"p. 151, 168"},{"id":"p207-qru-106","type":"QRU","rank":"A","objective":"p207-obj-09","tags":["étiologie","imagerie"],"difficulty":1,"stem":"Une femme de 70 ans a une opacité du médiastin antérieur et supérieur découverte fortuitement, refoulant la trachée. Le scanner montre que la masse est en continuité avec le lobe thyroïdien et en partie calcifiée. Quel est le diagnostic ?","options":[{"t":"Goitre plongeant","ok":true,"why":"Continuité avec la glande thyroïde, souvent calcifiée : le scanner affirme le diagnostic."},{"t":"Kyste pleuro-péricardique","ok":false,"why":"Il siège dans l'angle cardio-phrénique (médiastin antérieur et inférieur)."},{"t":"Schwannome","ok":false,"why":"Tumeur neurogène du médiastin postérieur."},{"t":"Kyste bronchogénique","ok":false,"why":"Il siège dans le médiastin moyen, au contact de l'arbre bronchique."},{"t":"Lymphome thymique","ok":false,"why":"Les tumeurs thymiques siègent dans le médiastin antérieur et moyen ; la continuité avec la thyroïde est caractéristique du goitre."}],"explanation":"Le goitre plongeant, tumeur en général bénigne, siège dans le médiastin antérieur et supérieur ; typique, il ne nécessite pas de confirmation histologique.","src":"p. 151, 163"},{"id":"p207-qru-107","type":"QRU","rank":"B","objective":"p207-obj-09","tags":["urgence","diagnostic"],"difficulty":3,"stem":"Un homme de 24 ans est en détresse par compression médiastinale aiguë due à une volumineuse masse du médiastin antérieur ; une tumeur germinale non séminomateuse est suspectée. Sur quel élément peut-on porter le diagnostic sans attendre la preuve histologique ?","options":[{"t":"Une fixation intense de la masse en TEP-FDG","ok":false,"why":"La TEP n'est jamais formelle et n'est pas le critère cité ici."},{"t":"Un aspect en pop-corn au scanner","ok":false,"why":"Il est pathognomonique de l'hamartochondrome, nodule bénin."},{"t":"Une myasthénie associée au tableau","ok":false,"why":"Elle oriente vers une tumeur épithéliale du thymus, pas vers une tumeur germinale."},{"t":"Une élévation franche de l'AFP ou de l'HCG","ok":true,"why":"Le diagnostic de TGNS peut être porté sur ce seul critère biologique."},{"t":"Une continuité de la masse avec la glande thyroïde","ok":false,"why":"Elle caractérise le goitre plongeant."}],"explanation":"En urgence vitale chez un homme jeune suspect de TGNS, l'élévation franche de l'AFP ou de l'HCG suffit ; si les marqueurs sont négatifs, un abord histologique est nécessaire.","src":"p. 169-170"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"p207-pareto","points":[{"id":"p207-par-01","rank":"A","cat":"définition","text":"Nodule = opacité intraparenchymateuse de **3 à 30 mm** ; micronodule **< 3 mm** ; masse **> 3 cm** (mesures au scanner)","src":"p. 151-152"},{"id":"p207-par-02","rank":"A","cat":"examen","text":"Nodule : examen clé = **scanner thoracique** ; **radiographie** inadaptée à la découverte et **sans place** dans le dépistage du cancer du poumon","src":"p. 151, 153"},{"id":"p207-par-03","rank":"A","cat":"clinique","text":"Présomption de **malignité** : terrain (tabac), taille, morphologie, **TEP-FDG**, évolution ; certitude = **histologie** seule","src":"p. 151, 154"},{"id":"p207-par-04","rank":"A","cat":"clinique","text":"Haut risque de malignité : **contours spiculés**, **lobes supérieurs**, **progression** en taille ou en volume (+ tabac, âge, fixation TEP élevée)","src":"p. 154"},{"id":"p207-par-05","rank":"A","cat":"clinique","text":"Bénin : **calcifications** (complète, centrale, lamellaire), stabilité **2 ans** (solide) ou **3-5 ans** (verre dépoli)","src":"p. 154, 156"},{"id":"p207-par-06","rank":"A","cat":"étiologie","text":"**Hamartochondrome** = tumeur bénigne la plus fréquente : aspect en **pop-corn** (calcifications + densités graisseuses)","src":"p. 156"},{"id":"p207-par-07","rank":"A","cat":"piège","text":"TEP-FDG : **faux négatifs** (nodule < 1 cm, verre dépoli pur) ; **faux positifs** (granulomes, infections : mycobactérioses, aspergillose, sarcoïdose)","src":"p. 153"},{"id":"p207-par-08","rank":"A","cat":"définition","text":"Médiastin = **9 loges** (3 étages × 3 compartiments) ; orientation étiologique = **localisation précise** de la masse","src":"p. 151, 162-163"},{"id":"p207-par-09","rank":"A","cat":"examen","text":"Masse du médiastin : **TDM** (antérieur et moyen), complétée par **IRM** (postérieur)","src":"p. 151"},{"id":"p207-par-10","rank":"A","cat":"examen","text":"Lésions typiques (**goitres**, **kystes**) : pas de preuve histologique nécessaire ; tumeur potentiellement maligne : preuve histologique","src":"p. 151, 169"},{"id":"p207-par-11","rank":"A","cat":"étiologie","text":"Antérieur : **goitre plongeant** (sup.), **thymus/tératome/tumeur germinale** (moyen), **kyste pleuro-péricardique** (inf.)","src":"p. 163-166"},{"id":"p207-par-12","rank":"A","cat":"étiologie","text":"Médiastin moyen : **adénopathies** (1re cause), **kyste bronchogénique** ; postérieur : **tumeurs neurogènes** (schwannome chez l'adulte)","src":"p. 167-168"},{"id":"p207-par-13","rank":"A","cat":"examen","text":"Tumeur du médiastin antérieur : doser **AFP et HCG** ; homme jeune en urgence vitale : élévation franche = **TGNS** sans biopsie","src":"p. 168-170"},{"id":"p207-par-14","rank":"A","cat":"examen","text":"Nodule : prélèvement par l'examen **le moins invasif** d'abord (adénopathie accessible) ; ponction transpariétale → **pneumothorax 10-20 %**","src":"p. 160"},{"id":"p207-par-15","rank":"B","cat":"traitement","text":"Cancer primitif confirmé sur l'exérèse du nodule (extemporanée) : compléter par **lobectomie** + **curage** ganglionnaire","src":"p. 160"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
